public final class Solution {
    private Solution() {}

    public static int[] fitSize(int sourceWidth, int sourceHeight,
                                int limitWidth, int limitHeight) {
        if (sourceWidth <= 0 || sourceHeight <= 0
                || limitWidth <= 0 || limitHeight <= 0) {
            throw new IllegalArgumentException("Dimensions must be positive");
        }
        int scale = Math.min(1,
                Math.min(limitWidth / sourceWidth, limitHeight / sourceHeight));
        int width = Math.max(1, (int) Math.floor(sourceWidth * scale));
        int height = Math.max(1, (int) Math.floor(sourceHeight * scale));
        return new int[] { width, height };
    }
}
